// --- filtre des coordonnées (copie de js/filtre-coordonnees.js)
// Nikah — détection des coordonnées (téléphone, e-mail, réseaux sociaux, liens, demandes de contact hors du site)
// Le même code tourne dans le navigateur et sur le serveur (n8n). Retourne null si le message est autorisé,
// sinon le type de coordonnée détectée : "telephone", "email", "reseau", "lien" ou "demande".
var NikahFiltre = (function () {
  "use strict";

  var CHIFFRES_MOTS = {
    // français
    zero: "0", un: "1", une: "1", deux: "2", trois: "3", quatre: "4", cinq: "5", six: "6", sept: "7", huit: "8", neuf: "9",
    dix: "10", onze: "11", douze: "12", treize: "13", quatorze: "14", quinze: "15", seize: "16", cette: "7", neuve: "9",
    // anglais
    oh: "0", one: "1", two: "2", three: "3", four: "4", five: "5", seven: "7", eight: "8", nine: "9", ten: "10",
    // allemand
    null: "0", eins: "1", zwei: "2", zwo: "2", drei: "3", vier: "4", funf: "5", fuenf: "5", sechs: "6", sieben: "7", acht: "8", neun: "9", zehn: "10",
    // italien
    uno: "1", due: "2", tre: "3", quattro: "4", cinque: "5", sei: "6", sette: "7", otto: "8", nove: "9", dieci: "10",
    // albanais
    nje: "1", dy: "2", kater: "4", pese: "5", gjashte: "6", shtate: "7", tete: "8", nente: "9",
    // arabe (écriture arabe et translittération courante)
    "صفر": "0", "واحد": "1", "اثنان": "2", "اثنين": "2", "زوج": "2", "ثلاثة": "3", "ثلاث": "3", "أربعة": "4", "اربعة": "4", "خمسة": "5", "ستة": "6", "سبعة": "7", "ثمانية": "8", "تسعة": "9",
    sifr: "0", wahed: "1", wa7ed: "1", jouj: "2", tnin: "2", tlata: "3", arba: "4", khamsa: "5", setta: "6", sab3a: "7", tmanya: "8", tes3a: "9"
  };
  var DIZAINES = {
    vingt: "2", trente: "3", quarante: "4", cinquante: "5", soixante: "6", septante: "7", huitante: "8", octante: "8", nonante: "9",
    twenty: "2", thirty: "3", forty: "4", fifty: "5", sixty: "6", seventy: "7", eighty: "8", ninety: "9",
    venti: "2", trenta: "3", quaranta: "4", cinquanta: "5", sessanta: "6", settanta: "7", ottanta: "8", novanta: "9"
  };
  var LIANTS = { et: 1, puis: 1, apres: 1, and: 1, then: 1, le: 1, la: 1, c: 1, est: 1, cest: 1, und: 1, e: 1, plus: 1 };

  // Mots longs repérés même s'ils sont écrits avec des espaces, des points ou des chiffres à la place des lettres
  var RESEAUX_COLLES = ["whatsapp", "whatsap", "watsap", "watsapp", "wathsapp", "whatapp", "telegram", "snapchat", "instagram", "facebook", "messenger",
    "tiktok", "viber", "skype", "discord", "linkedin", "wechat", "threema"];
  var EMAILS_COLLES = ["gmail", "hotmail", "outlook", "yahoo", "icloud", "protonmail", "bluewin", "laposte", "wanadoo"];
  var RESEAUX_MOTS = /(^|\s)(snap|insta|whats|wsp|wtsp|wtsap|ig|fb|tg|imo|signal app|sur signal|on signal|tele|telegrame)(\s|$)/;
  var RESEAUX_ARABE = /(واتساب|واتس|وتساب|تلغرام|تيليجرام|انستغرام|انستقرام|انستا|سناب|فيسبوك|فيس بوك|ايميل|إيميل|الإيميل|رقمك|رقم هاتفك|رقم الهاتف|هاتفك|تلفونك|جوالك|نمرتك|النمرة)/;
  var DEMANDES = new RegExp(
    "(\\b(ton|ta|tes|votre|vos|mon|ma|mes|your|my|dein|deine|deinen|meine|mein|meinen|tuo|tua|il tuo|la tua|mio|mia|jot|im|yt)\\s+(\\w+\\s+)?" +
    "(numero|num|numeros|tel|tele|telephone|portable|natel|mobile|cell|cellulaire|cellulare|handy|handynummer|nummer|telefon|telefonnummer|telefono|phone|number|mail|email|mails|adresse mail|adresse email|contact|contacts|coordonnees|numri|numrin|telefoni|telefonin)\\b)" +
    "|\\b(numri|numrin|telefoni|telefonin|emaili|emailin|numero|nummer)\\s+(tend|tuaj|tuo|tua|vostro|di te)\\b" +
    "|\\b(appelle moi|appelez moi|appele moi|je t appelle|je vous appelle|on s appelle|on peut s appeler|tu peux m appeler|call me|text me|ruf mich an|chiamami|ecris moi sur|ecris moi en prive|ecrivez moi sur|en prive|en mp|hors du site|hors de la plateforme|hors plateforme|ailleurs qu ici|ajoute moi|ajoutez moi|add me|contacte moi sur|contactez moi sur)\\b");

  function normaliser(t) {
    var s = String(t || "");
    try { s = s.normalize("NFKC"); } catch (e) { /* ancien navigateur */ }
    s = s.replace(/[٠-٩]/g, function (c) { return String(c.charCodeAt(0) - 0x0660); })
         .replace(/[۰-۹]/g, function (c) { return String(c.charCodeAt(0) - 0x06F0); })
         .replace(/[️⃣​-‍⁠]/g, "");
    try { s = s.normalize("NFD"); } catch (e) { /* ignoré */ }
    return s.replace(/[̀-ͯ]/g, "").toLowerCase();
  }
  function leet(s) {
    return s.replace(/0/g, "o").replace(/1/g, "i").replace(/3/g, "e").replace(/4/g, "a").replace(/5/g, "s").replace(/7/g, "t").replace(/@/g, "a").replace(/\$/g, "s").replace(/\|/g, "i");
  }

  function chiffres(s) {
    // Enlève dates et heures pour ne pas les confondre avec un numéro
    s = s.replace(/\b\d{1,2}\s*[.\/-]\s*\d{1,2}\s*[.\/-]\s*\d{2,4}\b/g, " ")
         .replace(/\b\d{1,2}\s*[h:]\s*\d{2}\b/g, " ");
    var mots = s.replace(/[-_'’]/g, " ").split(/[^a-z0-9+؀-ۿ]+/).filter(Boolean);
    var meilleur = 0, courant = "", trous = 0;
    function fin() { if (courant.length > meilleur) meilleur = courant.length; courant = ""; trous = 0; }
    for (var i = 0; i < mots.length; i++) {
      var m = mots[i], ajout = null;
      if (/^\+?\d+$/.test(m)) ajout = m.replace("+", "");
      else if (/^[0-9oil]+$/.test(m) && /\d/.test(m)) ajout = m.replace(/o/g, "0").replace(/[il]/g, "1");
      else if (/^[a-z]*\d[a-z0-9]*$/.test(m) && m.replace(/\d/g, "").length <= 2) ajout = m.replace(/[^0-9]/g, "");
      else if (CHIFFRES_MOTS.hasOwnProperty(m)) ajout = CHIFFRES_MOTS[m];
      else if (DIZAINES.hasOwnProperty(m)) {
        var suivant = mots[i + 1];
        if (suivant && CHIFFRES_MOTS.hasOwnProperty(suivant) && CHIFFRES_MOTS[suivant].length === 1) { ajout = DIZAINES[m] + CHIFFRES_MOTS[suivant]; i++; }
        else ajout = DIZAINES[m] + "0";
      }
      if (ajout !== null) { courant += ajout; trous = 0; }
      else if (LIANTS[m] && courant && trous < 1) trous++;
      else fin();
    }
    fin();
    return meilleur;
  }

  function detecter(texte) {
    var s = normaliser(texte);
    if (!s.trim()) return null;
    var espaces = " " + s.replace(/[^a-z0-9@؀-ۿ]+/g, " ") + " ";
    var colle = leet(s).replace(/[^a-z]/g, "");

    // Téléphone : au moins 8 chiffres à la suite (chiffres, mots ou mélange), ou indicatif international
    if (chiffres(s) >= 8) return "telephone";
    if (/(\+|\b00)\s*\d{2,3}[\s.\-\/]*\d{2,}/.test(s) && chiffres(s) >= 6) return "telephone";

    // E-mail
    if (/[a-z0-9._%+\-]+\s*@\s*[a-z0-9\-]+/.test(s)) return "email";
    if (/[a-z0-9._\-]{2,}\s*(\(at\)|\[at\]|\{at\}|\sat\s|\sarobase\s|\sarrobase\s|\sa commercial\s)\s*[a-z0-9\-]{2,}/.test(" " + s + " ")) return "email";
    for (var i = 0; i < EMAILS_COLLES.length; i++) if (colle.indexOf(EMAILS_COLLES[i]) !== -1) return "email";

    // Liens et adresses de sites
    if (/https?:|www\s*\.|\b(wa\.me|t\.me|bit\.ly|linktr\.ee)\b/.test(s)) return "lien";
    if (/\b[a-z0-9\-]{2,}\s*(\.|\(dot\)|\[dot\]|\sdot\s|\spoint\s)\s*(com|ch|fr|net|org|me|be|de|it|io|ly|gl|al|ma|dz|tn|info|co)\b/.test(s)) return "lien";

    // Réseaux sociaux et messageries
    for (var j = 0; j < RESEAUX_COLLES.length; j++) if (colle.indexOf(RESEAUX_COLLES[j]) !== -1) return "reseau";
    if (RESEAUX_MOTS.test(" " + leet(espaces).replace(/\s+/g, " ") + " ")) return "reseau";
    if (RESEAUX_ARABE.test(s)) return "reseau";

    // Demandes de contact hors du site
    if (DEMANDES.test(espaces.replace(/\s+/g, " "))) return "demande";
    return null;
  }

  // Vérifie aussi les numéros coupés en plusieurs messages (derniers messages de la même personne)
  function detecterSuite(texte, precedents) {
    var direct = detecter(texte);
    if (direct) return direct;
    var tout = (precedents || []).slice(-5).concat([texte]).join(" ");
    return chiffres(normaliser(tout)) >= 8 ? "telephone" : null;
  }

  var MESSAGE = "Pour la sécurité de tous, les numéros de téléphone, adresses e-mail, réseaux sociaux, liens et demandes de contact hors du site sont interdits. Tous les échanges se font ici, sur Nikah.";
  return { detecter: detecter, detecterSuite: detecterSuite, MESSAGE: MESSAGE };
})();
if (typeof module !== "undefined") module.exports = NikahFiltre;

// --- fin du filtre
const b = $input.first().json.body || {};
const token = String(b.token || '');
const action = String(b.action || '');
if (!/^[a-f0-9]{64}$/.test(token)) return [{ json: { ok: false, error: 'session_invalide' } }];
if (['list', 'start', 'send', 'open', 'answer', 'block', 'unblock', 'report'].indexOf(action) === -1) return [{ json: { ok: false, error: 'requete_invalide' } }];
const esc = (s) => "'" + String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\0/g, '') + "'";
const SES = "me.session_hash=SHA2('" + token + "',256) AND me.session_expires > NOW() AND me.status='actif'";
const cid = parseInt(b.cid, 10);
const to = parseInt(b.to, 10);
const body = String(b.body || '').replace(/\r/g, '').trim();
const SKIP = 'SELECT 1';
const VIS = "(c.member_a=me.id OR (c.member_b=me.id AND c.status NOT IN ('moderation','rejetee')))";
const BLK = (x, y) => "NOT EXISTS (SELECT 1 FROM member_blocks bk WHERE ((bk.blocker_id=" + x + " AND bk.blocked_id=" + y + ") OR (bk.blocker_id=" + y + " AND bk.blocked_id=" + x + ")) AND (bk.until IS NULL OR bk.until > NOW()))";
const OTHER = 'IF(c.member_a=me.id,c.member_b,c.member_a)';
let q0 = SKIP, q1 = SKIP, kind = 'thread', convCond = '';

const sendSql = (convJoin) => "INSERT INTO messages (conversation_id,sender_id,body) SELECT c.id, me.id, " + esc(body) + " FROM members me JOIN conversations c ON " + convJoin + " AND (c.member_a=me.id OR c.member_b=me.id) WHERE " + SES + " AND (c.status='acceptee' OR (c.status IN ('demande','moderation') AND c.member_a=me.id AND NOT EXISTS (SELECT 1 FROM messages m2 WHERE m2.conversation_id=c.id))) AND " + BLK('c.member_a', 'c.member_b');

if (action === 'list') {
  kind = 'list';
} else if (action === 'start') {
  if (!Number.isInteger(to) || to < 1 || body.length < 1 || body.length > 1000) return [{ json: { ok: false, error: 'requete_invalide' } }];
  q0 = "INSERT IGNORE INTO conversations (member_a,member_b,pair_lo,pair_hi,status) SELECT me.id, o.id, LEAST(me.id,o.id), GREATEST(me.id,o.id), 'moderation' FROM members me JOIN members o ON o.id=" + to + " AND o.id<>me.id AND o.status='actif' AND o.identity_verified=1 AND o.gender<>me.gender JOIN profiles mp ON mp.member_id=me.id JOIN search_preferences ms ON ms.member_id=me.id JOIN profiles op ON op.member_id=o.id JOIN search_preferences os ON os.member_id=o.id WHERE " + SES + " AND me.identity_verified=1 AND (YEAR(CURDATE()) - op.birth_year) BETWEEN ms.age_min AND ms.age_max AND (YEAR(CURDATE()) - mp.birth_year) BETWEEN os.age_min AND os.age_max AND " + BLK('me.id', 'o.id');
  q1 = sendSql("c.pair_lo=LEAST(me.id," + to + ") AND c.pair_hi=GREATEST(me.id," + to + ")");
  convCond = "c.pair_lo=LEAST(me.id," + to + ") AND c.pair_hi=GREATEST(me.id," + to + ")";
} else {
  if (!Number.isInteger(cid) || cid < 1) return [{ json: { ok: false, error: 'requete_invalide' } }];
  convCond = "c.id=" + cid;
  if (action === 'send') {
    if (body.length < 1 || body.length > 1000) return [{ json: { ok: false, error: 'requete_invalide' } }];
    q1 = sendSql("c.id=" + cid);
  } else if (action === 'open') {
    q0 = "UPDATE messages m JOIN conversations c ON c.id=m.conversation_id JOIN members me ON " + VIS + " AND " + SES + " SET m.read_at=NOW() WHERE c.id=" + cid + " AND m.sender_id<>me.id AND m.read_at IS NULL";
  } else if (action === 'answer') {
    const st = b.accept === true ? 'acceptee' : 'refusee';
    q0 = "UPDATE conversations c JOIN members me ON c.member_b=me.id AND " + SES + " SET c.status='" + st + "' WHERE c.id=" + cid + " AND c.status='demande'";
  } else if (action === 'block') {
    const DUREES = { '24h': 'DATE_ADD(NOW(), INTERVAL 1 DAY)', '7j': 'DATE_ADD(NOW(), INTERVAL 7 DAY)', '30j': 'DATE_ADD(NOW(), INTERVAL 30 DAY)', 'definitif': 'NULL' };
    const fin = DUREES[String(b.duree || '')];
    if (!fin) return [{ json: { ok: false, error: 'requete_invalide' } }];
    q0 = "INSERT INTO member_blocks (blocker_id, blocked_id, until) SELECT me.id, " + OTHER + ", " + fin + " FROM members me JOIN conversations c ON c.id=" + cid + " AND (c.member_a=me.id OR c.member_b=me.id) WHERE " + SES + " ON DUPLICATE KEY UPDATE until=VALUES(until), created_at=NOW()";
  } else if (action === 'unblock') {
    q0 = "DELETE bk FROM member_blocks bk JOIN members me ON bk.blocker_id=me.id AND " + SES + " JOIN conversations c ON c.id=" + cid + " AND (c.member_a=me.id OR c.member_b=me.id) WHERE bk.blocked_id=" + OTHER;
  } else if (action === 'report') {
    const MOTIFS = ['propos_deplaces', 'harcelement', 'faux_profil', 'demande_argent', 'coordonnees', 'autre'];
    const motif = String(b.motif || '');
    const details = String(b.details || '').replace(/\r/g, '').trim();
    if (MOTIFS.indexOf(motif) === -1 || details.length > 1000) return [{ json: { ok: false, error: 'requete_invalide' } }];
    q0 = "INSERT INTO member_reports (reporter_id, reported_id, conversation_id, reason, details) SELECT me.id, " + OTHER + ", c.id, " + esc(motif) + ", " + esc(details) + " FROM members me JOIN conversations c ON c.id=" + cid + " AND " + VIS + " WHERE " + SES + " AND NOT EXISTS (SELECT 1 FROM member_reports rp WHERE rp.reporter_id=me.id AND rp.conversation_id=c.id AND rp.status='nouveau' AND rp.reason<>'filtre_auto')";
  }
}

let filtre = null;
if (action === 'start' || action === 'send') {
  filtre = NikahFiltre.detecter(body);
  if (filtre) {
    q0 = SKIP;
    const det = esc('Message bloqué automatiquement (' + filtre + ') : ' + body.slice(0, 900));
    q1 = action === 'send'
      ? "INSERT INTO member_reports (reporter_id, reported_id, conversation_id, reason, details) SELECT me.id, me.id, c.id, 'filtre_auto', " + det + " FROM members me JOIN conversations c ON c.id=" + cid + " AND (c.member_a=me.id OR c.member_b=me.id) WHERE " + SES
      : "INSERT INTO member_reports (reporter_id, reported_id, conversation_id, reason, details) SELECT me.id, me.id, (SELECT c.id FROM conversations c WHERE c.pair_lo=LEAST(me.id," + to + ") AND c.pair_hi=GREATEST(me.id," + to + ")), 'filtre_auto', " + det + " FROM members me WHERE " + SES;
  }
}
let q2;
if (kind === 'list') {
  q2 = "SELECT me.id AS me_id, c.id AS cid, c.status, c.member_a AS init, o.id AS oid, o.display_name, o.gender AS ogenre, o.avatar_color, o.identity_verified AS overifie, (YEAR(CURDATE()) - op.birth_year) AS oage, op.city AS oville, op.region AS oregion, (SELECT body FROM messages WHERE conversation_id=c.id ORDER BY id DESC LIMIT 1) AS dernier, (SELECT COUNT(*) FROM messages WHERE conversation_id=c.id AND sender_id<>me.id AND read_at IS NULL) AS non_lus, (SELECT MAX(id) FROM messages WHERE conversation_id=c.id) AS dernier_id " +
    "FROM (SELECT 1 AS x) d LEFT JOIN members me ON " + SES + " LEFT JOIN conversations c ON me.id IS NOT NULL AND " + VIS + " LEFT JOIN members o ON o.id=IF(c.member_a=me.id,c.member_b,c.member_a) LEFT JOIN profiles op ON op.member_id=o.id ORDER BY dernier_id DESC, c.id DESC LIMIT 100";
} else {
  q2 = "SELECT me.id AS me_id, c.id AS cid, c.status, c.member_a AS init, o.id AS oid, o.display_name, o.gender AS ogenre, o.avatar_color, o.identity_verified AS overifie, (YEAR(CURDATE()) - op.birth_year) AS oage, op.city AS oville, op.region AS oregion, (SELECT IFNULL(DATE_FORMAT(bk.until,'%Y-%m-%dT%H:%i'),'definitif') FROM member_blocks bk WHERE bk.blocker_id=me.id AND bk.blocked_id=o.id AND (bk.until IS NULL OR bk.until > NOW())) AS bloque_moi, (SELECT COUNT(*) FROM member_blocks bk WHERE bk.blocker_id=o.id AND bk.blocked_id=me.id AND (bk.until IS NULL OR bk.until > NOW())) AS bloque_lui, (SELECT COUNT(*) FROM member_reports rp WHERE rp.reporter_id=me.id AND rp.conversation_id=c.id AND rp.status='nouveau' AND rp.reason<>'filtre_auto') AS deja_signale, m.id AS mid, m.sender_id, m.body, m.created_at AS mdate " +
    "FROM (SELECT 1 AS x) d LEFT JOIN members me ON " + SES + " LEFT JOIN conversations c ON me.id IS NOT NULL AND " + convCond + " AND " + VIS + " LEFT JOIN members o ON o.id=IF(c.member_a=me.id,c.member_b,c.member_a) LEFT JOIN profiles op ON op.member_id=o.id LEFT JOIN messages m ON m.conversation_id=c.id ORDER BY m.id ASC LIMIT 300";
}
return [{ json: { ok: true, kind, q0, q1, q2, filtre } }];

const kind = $('Prepare').first().json.kind;
const filtre = $('Prepare').first().json.filtre;
const rows = $input.all().map(i => i.json);
if (!rows.length || rows[0].me_id === null || rows[0].me_id === undefined) return [{ json: { success: false, error: 'session_invalide' } }];
const me = Number(rows[0].me_id);
if (filtre) return [{ json: { success: false, error: 'coordonnees_interdites', type: filtre } }];
const autre = (r) => ({ id: r.oid === null || r.oid === undefined ? null : Number(r.oid), nom: r.display_name, genre: r.ogenre, age: r.oage === null ? null : Number(r.oage), couleur: r.avatar_color, verifie: Number(r.overifie) === 1, ville: r.oville || null, region: r.oregion || null });
if (kind === 'list') {
  const convs = rows.filter(r => r.cid !== null && r.cid !== undefined).map(r => ({
    cid: r.cid, statut: r.status, initiateur: Number(r.init) === me, autre: autre(r),
    dernier: r.dernier, non_lus: Number(r.non_lus || 0)
  }));
  return [{ json: { success: true, conversations: convs, non_lus: convs.reduce((t, c) => t + c.non_lus, 0) } }];
}
const premiere = rows.find(r => r.cid !== null && r.cid !== undefined);
if (!premiere) return [{ json: { success: false, error: 'introuvable' } }];
return [{ json: { success: true, cid: premiere.cid, statut: premiere.status, initiateur: Number(premiere.init) === me, autre: autre(premiere),
  blocage: { par_moi: premiere.bloque_moi || null, par_lui: Number(premiere.bloque_lui || 0) > 0 }, deja_signale: Number(premiere.deja_signale || 0) > 0,
  messages: rows.filter(r => r.mid !== null && r.mid !== undefined).map(r => ({ id: r.mid, moi: Number(r.sender_id) === me, texte: r.body, date: r.mdate })) } }];
